import java.util.Scanner;

class Student {
    int m1, m2, m3;

    Student(int m1, int m2, int m3) {
        this.m1 = m1;
        this.m2 = m2;
        this.m3 = m3;
    }

    double average() {
        return (m1 + m2 + m3) / 3.0;
    }

    String grade() {
        double avg = average();

        if (avg >= 90)
            return "A";
        else if (avg >= 75)
            return "B";
        else if (avg >= 60)
            return "C";
        else
            return "D";
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        Student s = new Student(
            sc.nextInt(),
            sc.nextInt(),
            sc.nextInt()
        );

        System.out.printf("Average: %.1f%n", s.average());
        System.out.println("Grade: " + s.grade());
    }
}

